// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address caller, uint256 amount) public {
        amount = bound(amount, 0, 1 ether);

        vm.deal(caller, amount);

        uint256 before = c.depositsCount();

        vm.prank(caller);
        (bool ok, ) = payable(address(c)).call{value: amount}("");
        require(ok);

        uint256 afterCount = c.depositsCount();
        assertTrue(afterCount == before + 1);
    }
}
